.holy-grail-layout {
  display: grid;
  grid-template-areas:
    "header header header"
    "nav main aside"
    "footer footer footer";
  grid-template-columns: minmax(200px, 260px) 1fr minmax(200px, 260px);
  grid-template-rows: auto 1fr auto;
  min-height: 100vh;
  gap: 1rem;
}

.site-header { grid-area: header; }
.site-nav    { grid-area: nav; }
.site-main   { grid-area: main; }
.site-aside  { grid-area: aside; }
.site-footer { grid-area: footer; }

@media (max-width: 768px) {
  .holy-grail-layout {
    grid-template-areas:
      "header"
      "nav"
      "main"
      "aside"
      "footer";
    grid-template-columns: 1fr;
  }
}

:root {
  --font-base: clamp(1rem, 0.75rem + 1.25vw, 1.25rem);
  --font-h1: clamp(2rem, 1.5rem + 2.5vw, 3.5rem);
  --font-h2: clamp(1.5rem, 1.25rem + 1.5vw, 2.25rem);
  --space-unit: clamp(0.5rem, 0.25rem + 1vw, 1.5rem);
}

body {
  font-size: var(--font-base);
  line-height: 1.6;
}

h1 {
  font-size: var(--font-h1);
  line-height: 1.2;
  letter-spacing: -0.02em;
}

h2 {
  font-size: var(--font-h2);
  line-height: 1.3;
}

@media print {
  @page {
    margin: 20mm;
    size: auto;
  }
  *, *::before, *::after {
    background: transparent !important;
    color: #000 !important;
    box-shadow: none !important;
    text-shadow: none !important;
  }
  body {
    font-size: 12pt;
    line-height: 1.4;
    color: #000;
  }
  nav, aside, .skip-link, button, form, .no-print {
    display: none !important;
  }
  h1, h2, h3, h4, h5, h6 {
    break-after: avoid;
    page-break-after: avoid;
  }
  p, blockquote {
    orphans: 3;
    widows: 3;
  }
  pre, blockquote, table, img, figure {
    break-inside: avoid;
    page-break-inside: avoid;
  }
  a[href^="http"]::after {
    content: " (" attr(href) ")";
    font-size: 0.85em;
    word-break: break-all;
  }
  .print-only {
    display: block !important;
  }
}

@layer reset, base, layout, components, utilities;

@layer reset {
  *, *::before, *::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }
}

@layer base {
  body {
    font-family: system-ui, -apple-system, sans-serif;
    color: #1a1a1a;
    background-color: #fafafa;
  }
}

@layer components {
  /* :where() gives 0-0-0 specificity: highly overridable defaults */
  :where(.btn, .card, .badge) {
    border-radius: 0.375rem;
    transition: background-color 150ms ease;
  }
  /* :is() takes the specificity of its most specific argument */
  :is(header, footer, main) > .content-wrapper {
    max-width: 1200px;
    margin-inline: auto;
  }
  .btn {
    display: inline-flex;
    padding: 0.5rem 1rem;
    background: #2563eb;
    color: #fff;
  }
}

@layer utilities {
  .u-hidden {
    display: none;
  }
}

export interface AgentConfig {
  readonly seatId: number;
  readonly model: string;
  readonly vramLimitMb: number;
  readonly roles: readonly ('compiler' | 'systems' | 'web' | 'lora')[];
}

export const SEAT_SETTINGS = {
  seatId: 3,
  model: 'qwen3.5-9b-abli',
  vramLimitMb: 7372,
  roles: ['compiler', 'lora'] as const,
} satisfies AgentConfig;

export type MeshEvent =
  | { kind: 'HEARTBEAT'; seat: number; timestamp: string }
  | { kind: 'CLAIM'; seat: number; path: string; intent: string }
  | { kind: 'RELEASE'; seat: number; path: string };

export function formatEvent(event: MeshEvent): string {
  switch (event.kind) {
    case 'HEARTBEAT': return `[HB] Seat ${event.seat}`;
    case 'CLAIM':     return `[LOCK] Seat ${event.seat} -> ${event.path}`;
    case 'RELEASE':   return `[FREE] Seat ${event.seat} -> ${event.path}`;
    default: {
      const _exhaustive: never = event;
      throw new Error(`Unhandled event: ${_exhaustive}`);
    }
  }
}

export interface HeartbeatPayload {
  readonly seatId: number;
  readonly status: 'active' | 'stale';
  readonly timestampEpoch: number;
}

export interface LockAcquiredPayload {
  readonly seatId: number;
  readonly resourcePath: string;
  readonly leaseEpoch: number;
}

export interface TaskDispatchedPayload {
  readonly taskId: string;
  readonly seatId: number;
  readonly payloadJson: string;
}

export type MeshProtocolEvent =
  | { readonly kind: 'HEARTBEAT'; readonly data: HeartbeatPayload }
  | { readonly kind: 'LOCK_ACQUIRED'; readonly data: LockAcquiredPayload }
  | { readonly kind: 'TASK_DISPATCHED'; readonly data: TaskDispatchedPayload };

export function assertNever(x: never, message?: string): never {
  throw new Error(message ?? `Unexpected unreachable value: ${JSON.stringify(x)}`);
}

export function processMeshEvent(event: MeshProtocolEvent): string {
  switch (event.kind) {
    case 'HEARTBEAT':
      return `[HB] Seat ${event.data.seatId} is ${event.data.status}`;
    case 'LOCK_ACQUIRED':
      return `[LOCK] Seat ${event.data.seatId} locked ${event.data.resourcePath}`;
    case 'TASK_DISPATCHED':
      return `[TASK] Task ${event.data.taskId} dispatched to Seat ${event.data.seatId}`;
    default:
      return assertNever(event);
  }
}

export type Primitive = string | number | boolean | bigint | symbol | null | undefined;

export type DeepReadonly<T> = T extends Primitive
  ? T
  : T extends (...args: readonly any[]) => any
  ? T
  : { readonly [K in keyof T]: DeepReadonly<T[K]> };

export function getNestedProperty<
  TObject extends Record<string, any>,
  TKey extends keyof TObject
>(target: TObject, key: TKey): TObject[TKey] {
  return target[key];
}

export function createRecordMap<
  const TKeys extends readonly string[],
  TValue
>(keys: TKeys, initialValue: TValue): Record<TKeys[number], TValue> {
  const result = {} as Record<TKeys[number], TValue>;
  for (const key of keys) {
    result[key as TKeys[number]] = initialValue;
  }
  return result;
}

export function mergeEntities<
  TBase extends { readonly id: string | number },
  TExtension extends Record<string, unknown>
>(base: TBase, extension: TExtension): TBase & TExtension {
  return Object.assign({}, base, extension);
}

