import type { IncomingMessage, ServerResponse } from 'node:http';
import { createServer } from 'node:http';

export const LogSeverity = {
  DEBUG: 'debug',
  INFO: 'info',
  WARN: 'warn',
  ERROR: 'error',
} as const;

export type LogLevel = (typeof LogSeverity)[keyof typeof LogSeverity];

export interface ServiceStatus {
  readonly nodeVersion: string;
  readonly uptimeSeconds: number;
  readonly severity: LogLevel;
}

export function formatServiceStatus(status: ServiceStatus): string {
  return `[NODE-${status.nodeVersion}] Status=${status.severity} Uptime=${status.uptimeSeconds}s`;
}

export const server = createServer((req: IncomingMessage, res: ServerResponse): void => {
  const status: ServiceStatus = {
    nodeVersion: process.version,
    uptimeSeconds: Math.floor(process.uptime()),
    severity: LogSeverity.INFO,
  };
  res.writeHead(200, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify(status));
});

export type Result<T, E = Error> =
  | { readonly ok: true; readonly value: T }
  | { readonly ok: false; readonly error: E };

export interface FetchOptions extends RequestInit {
  readonly timeoutMs?: number;
}

export async function safeFetchJson<T>(
  url: string,
  options: FetchOptions = {}
): Promise<Result<T, Error>> {
  const { timeoutMs = 5000, ...init } = options;
  const signal = options.signal ?? AbortSignal.timeout(timeoutMs);

  try {
    const response = await fetch(url, { ...init, signal });
    if (!response.ok) {
      return {
        ok: false,
        error: new Error(`HTTP Error ${response.status}: ${response.statusText}`),
      };
    }
    const data = (await response.json()) as T;
    return { ok: true, value: data };
  } catch (err: unknown) {
    if (err instanceof Error) {
      return { ok: false, error: err };
    }
    return { ok: false, error: new Error(String(err)) };
  }
}
